trading.extra_css:
.card, .tab, .btn, .az-btn, .az-seg span, .az-col, .stage[data-js="on"] .slots, .monad img { border-radius: var(--radius); }
.mesh, .az, .finale, .monad, .bench-wall .panel { border-radius: var(--radius-lg); }
.badge, .az-tag, .az-line { border-radius: var(--radius-sm); }
.bench-wall .panel { overflow: hidden; }
@media (prefers-reduced-motion: reduce) { .finale { animation: none; } }
[hidden] .controls { display: none; }
@media (scripting: none) { .idea span { animation: none; opacity: 1; transform: none; } }
.mnode text { font-size: 13px; stroke-width: 4px; }
.fp-mesh-note { display: none; margin: 0; color: var(--ink-dim); }
@container fp-carry (max-width: 830px) { .mesh figcaption, .mesh .meshsvg { display: none; } .mesh .fp-mesh-note { display: block; } }
